   517  int DecoderSession_finish_ok(DecoderSession *d)
   518  {
   519          FLAC__bool ok = true, md5_failure = false;
   520
   521          if(d->decoder) {
   522                  md5_failure = !FLAC__stream_decoder_finish(d->decoder) && !d->aborting_due_to_until;
